import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const n = Number(lines[0]);

// いもす法: 入った時刻に +1、出た時刻に -1 を記録し、最後に累積する
const diff = new Int32Array(1_000_001);
for (let i = 1; i <= n; i++) {
  const [s, t] = lines[i].split(" ").map(Number);
  diff[s]++;
  diff[t]--;
}
let cur = 0;
let best = 0;
for (let t = 0; t < diff.length; t++) {
  cur += diff[t];
  if (cur > best) best = cur;
}
console.log(best);
